{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Tofogliflozin, a close structural analogue of the query sharing the same C-aryl glucoside core, has a mean absolute oral bioavailability of 97.5% in healthy volunteers measured by a double-tracer IV/oral technique.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Safinamide has an absolute oral bioavailability of about 95% versus IV in healthy subjects under fasted conditions, supporting high oral absorption for small-molecule drugs in this transfer set.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Posaconazole fasted-state bioavailability was 56% in Western volunteers, still well above the 20% threshold, supporting a high F classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Drotaverine absolute oral bioavailability averaged 58.2% (range 24.5–91%) after an 80 mg oral dose, with essentially all observed values above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Sorafenib absolute oral bioavailability is approximately 50% under fasted conditions, providing additional evidence that even drugs with absorption limitations in this set remain above the 20% cutoff.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a very close structural analogue of tofogliflozin, whose human absolute oral bioavailability is 97.5%. Multiple additional high-transfer drugs with absolute bioavailability measurements in fasted or standard conditions also exceed 20% (safinamide ~95%, posaconazole fasted 56%, drotaverine mean 58%, sorafenib ~50%). The weight of direct and transferable experimental evidence strongly supports F >= 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule; the closest analogue, tofogliflozin, provides the strongest extrapolation.",
    "Fasted-state data are explicit for some analogues but not for tofogliflozin; however, its very high absolute bioavailability makes food-dependent failure above 20% unlikely.",
    "The impact of the ethoxy and chloro substituents on metabolism or transporter-mediated clearance is not directly measured, but the structural change is modest relative to the high-F parent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

